def ways_to_make_sum(n):
    modulo=1000000007;ways=[0]*(n+1);ways[0]=1
    for coin in (1,2,6):
        for total in range(coin,n+1):ways[total]=(ways[total]+ways[total-coin])%modulo
    return sum(ways[n-4*count] for count in range(3) if n>=4*count)%modulo

